class Solution:
    def distance(self, nums: List[int]) -> List[int]:
        groups = defaultdict(list)
        for i, v in enumerate(nums):
            groups[v].append(i)
        res = [0] * len(nums)
        for idx in groups.values():
            total, left, m = sum(idx), 0, len(idx)
            for k, j in enumerate(idx):
                right = total - left - j
                res[j] = (j * k - left) + (right - j * (m - 1 - k))
                left += j
        return res

