class Solution {
    public int numSubarrayProductLessThanK(int[] nums, int k) {
        int count = 0;
        for (int l = 0; l < nums.length; l++) {
            long prod = 1;
            for (int r = l; r < nums.length; r++) {
                prod *= nums[r];
                if (prod >= k) break;               // only grows from here
                count++;
            }
        }
        return count;
    }
}

