class Solution {
    public int sumSubseqWidths(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int mask = 1; mask < (1 << n); mask++) {
            int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
            for (int k = 0; k < n; k++) if ((mask >> k & 1) == 1) { mn = Math.min(mn, nums[k]); mx = Math.max(mx, nums[k]); }
