class Solution:
    def totalStrength(self, strength: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(strength)
        prev, nxt, st = [-1] * n, [n] * n, []
        for i, x in enumerate(strength):
            while st and strength[st[-1]] >= x:
                nxt[st.pop()] = i
            prev[i] = st[-1] if st else -1
            st.append(i)
        p = [0] * (n + 1)
        for i, x in enumerate(strength):
            p[i + 1] = p[i] + x
        pp = [0] * (n + 2)
        for i in range(n + 1):
            pp[i + 1] = pp[i] + p[i]
        total = 0
        for i, x in enumerate(strength):
            l, r = prev[i], nxt[i]
            total += x * ((pp[r + 1] - pp[i + 1]) * (i - l) - (pp[i + 1] - pp[l + 1]) * (r - i))
        return total % MOD

