        for v in order:
            for c in adj[v]:
                if c != parent[v]:
                    parent[c] = v
                    order.append(c)
        for v in reversed(order):
            size[v] += 1
            if v:
                size[parent[v]] += size[v]
                ans[0] += size[v]
        for v in order[1:]:
            ans[v] = ans[parent[v]] - size[v] + (n - size[v])
        return ans

